void bt_pskey_set(WORD key, WORD value_num, WORD *values)
{
	unsigned char *param = (unsigned char *)NEW(sizeof(unsigned char) *(USRPSK_LEN + value_num*2));
	int i;

	s_pskeys_num++;
	memset(param,0,(USRPSK_LEN + value_num*2));
	LOG("pskValueSet...");
	for(i=0; i<value_num; i++)
		LOG("%02X",values[i]);
	memcpy(param,SET_USRPSK_HEADER,17);
	param[3] = value_num + 8;
//	param[11]= (key & 0xff00) >> 8;
//	param[12]= key & 0x00ff;
	param[12]= (key & 0xff00) >> 8;
	param[11]= key & 0x00ff;
	param[13]= value_num;
	LOG("param[11] = %x param[12] = %x", param[11], param[12]);
	memcpy(param+17,values,value_num*2);
	APP_GAP_VendorCommand(HCI_EVI_VENDOR, 0, param, (USRPSK_LEN + value_num*2));
}

int bt_pskey_set_chip(int chip_type)
{
	PSKEYITEM *pskey = s_pskey_list[chip_type];
	int i;

	if (chip_type >= BT_PSKEY_CHIP_TYPE_NUM)
		return -1;

	for (i = 0; i < s_pskey_num[chip_type]; i++) {
		bt_pskey_set(pskey[i].wKey, pskey[i].wValNum, pskey[i].wValue);
	}

	return 0;
}

void APP_GAP_VendorCommandCbk(HANDLE hdl, void *context, void *par, UINT32 op_ev)
{
	struct HCI_VendorEvStru *vendor_ev = (struct HCI_VendorEvStru *)par;

	s_pskeys_cmp++;
	LOG("GAPVendorCommandCbk %d/%d", s_pskeys_cmp, s_pskeys_num);
	if (s_pskeys_cmp == s_pskeys_num) {
		LOG("[BCSP] set pskey complete! warm reset!");
		Bcsp_Clear();
		APP_CSR_WarmReset();
	}

	if (par) {
		FREE(par);
	}

	return NULL;
}

void APP_GAP_VendorCommand(UINT8 evi, UINT16 ocf, void *in_par, UINT8 in_par_size)
{
	UINT16 opcode = HCI_OPCODE(HCI_OGF_VENDOR, ocf);

	if (hci_cbk == NULL) {
		hci_cbk = List_NodeNew(sizeof(struct HCI_CbkLineStru));
		hci_cbk->id = opcode;
		hci_cbk->func = (HCI_CbkFunc *)APP_GAP_VendorCommandCbk;
		LOG("hci_cbk->func = %p", hci_cbk->func);
		HCI_Cbk_Reg(hci_cbk, 1);
	}
	HCI_Command_SendVendor(NULL, in_par, opcode, evi, in_par_size, UNKNOWNUM);
}

void APP_CSR_WarmReset(void)
{
	unsigned char *param = (unsigned char *)NEW(sizeof(unsigned char) *19);
	int i;
	memset(param,0,19);
	memcpy(param,WARMRESET,19);
	APP_GAP_VendorCommand(HCI_EVI_VENDOR, 0, param, 19);
}

int bt_pskey_set_from_conf()
{
	FILE *fp;
	WORD wKey;
	WORD wValue[124];
	WORD wValNum = 0;
	char line[MAXPATH] = {0};
	char tValue[MAXPATH] = {0};
	char project_ver[PROJECT_VERSION_LEN];
	char * s = NULL;
	char * k = NULL;

	memset(project_ver, 0, sizeof(project_ver));

	if((fp = fopen(PSK_PATH,"r")) == NULL) {
		LOG("bt_pskey_set_from_conf Read %s Error.", PSK_PATH);
		return -1;
	}

#ifdef CONFIG_PROJECT_ROSEN
// To set project version
	memset(line, 0, sizeof(line));
	fgets(line, MAXPATH, fp);
	if (strncmp(line, PROJECT_VERSION_TAG, strlen(PROJECT_VERSION_TAG)) == 0) {
		memcpy(project_ver, line+strlen(PROJECT_VERSION_TAG), PROJECT_VERSION_LEN);
		vendor_save_project_version(project_ver);
	}
#endif
// To set pskey.
	while(!feof(fp)) {
		wKey = 0;
		memset(wValue, 0 , 124);
		wValNum = 0;
		memset(line, 0, sizeof(line));
		if(fgets(line, MAXPATH, fp)) {
			char* context = (char*)malloc(strlen(line)+1);
			strcpy(context, line);
			s = strtok(context,"=");
			k = NULL;
			wKey = strtol(s+1, k, 16);
			while((s=strtok(NULL," ")) != NULL) {
				wValue[wValNum] = strtol(s, k, 16);
				wValNum ++;
			}
			int i = 0;
			char *p = tValue;
			for(i = 0; i < wValNum; i++) {
				sprintf(p, "%04x,", wValue[i]);
				p += 5;
			}
			LOG("wKey = %x,wValNum = %x, wValue = %s", wKey, wValNum, tValue);
			bt_pskey_set(wKey, wValNum, wValue);
			free(context);
		} else {
			break;
		}
	}
	fclose(fp);
	return 0;
}

void set_psk()
{
	s_pskeys_num = 0;
	s_pskeys_cmp = 0;
#ifdef CONFIG_TL_BCSP
	if (bt_pskey_set_from_conf() == -1) {
#if defined CONFIG_PROJECT_BC6
		bt_pskey_set_chip(BT_PSKEY_CHIP_TYPE_CSP_PATEO);
#elif defined CONFIG_PROJECT_ROSEN
		vendor_save_project_version("0000");
		//bt_pskey_set_chip(BT_PSKEY_CHIP_TYPE_ROSEN_8350);
#elif defined CONFIG_PROJECT_XXXX
		bt_pskey_set_chip(BT_PSKEY_CHIP_TYPE_CSR_8311);
#elif defined CONFIG_PROJECT_POLYCOM
		bt_pskey_set_chip(BT_PSKEY_CHIP_TYPE_CSR_8811);
#else
		//No need to set up pskey
		bt_pskey_set_chip(BT_PSKEY_CHIP_TYPE_DEFAULT);
#endif
	}
#endif
	//Don't need to execute warm reset function, because do after set pskey complete!
}

void psk_env_done(void)
{
	if (hci_cbk != NULL) {
		HCI_Cbk_UnReg(hci_cbk);
		LFREE(hci_cbk);
		hci_cbk = NULL;
	}
}
